SELECT s.s_store_id, s.s_store_name, p.p_promo_id, p.p_promo_name, SUM(ss.ss_net_paid) AS total_net_paid, SUM(ss.ss_quantity) AS total_quantity FROM store_sales ss INNER JOIN store s ON ss.ss_store_sk = s.s_store_sk INNER JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk WHERE ss.ss_sold_date_sk BETWEEN 2451112 AND 2451465 AND s.s_state = 'SC' GROUP BY s.s_store_id, s.s_store_name, p.p_promo_id, p.p_promo_name
